begin;
do $$declare a uuid;c uuid:=gen_random_uuid();p uuid:=gen_random_uuid();u uuid:=gen_random_uuid();r uuid:=gen_random_uuid();m uuid:=gen_random_uuid();g uuid:=gen_random_uuid();d jsonb:='{"title":"QA access risk","description":"QA synthetic site access issue","probability":"Medium","impact":"High","mitigation":"","status":"Open","resolution":""}';n integer:=0;begin
 select id into a from public.profiles where active and role='admin' order by id limit 1;if a is null then raise exception 'Administrator required';end if;perform set_config('request.jwt.claim.sub',a::text,true);perform set_config('request.jwt.claim.role','authenticated',true);
 insert into public.companies(id,name) values(c,'QA risk register company');insert into public.projects(id,company_id,title) values(p,c,'QA risk register project');insert into auth.users(id) values(u);insert into public.profiles(id,name,role,company_id) values(u,'QA risk client','client',c);
 insert into auth.users(id) values(m);insert into public.profiles(id,name,role) values(m,'QA risk manager','team');insert into public.crm_teams(id,name) values(g,'QA risk register team');insert into public.crm_memberships(user_id,role_id,team_id) values(m,'project_manager',g);insert into public.project_assignments(project_id,technician_id,assigned_by) values(p,m,a);
 perform set_config('request.jwt.claim.sub',a::text,true);perform set_config('request.jwt.claim.role','authenticated',true);execute 'set local role authenticated';
 perform public.save_project_risk(r,null,p,d,'QA record risk');if not exists(select 1 from public.crm_project_risks where id=r and version=1 and created_by=a) then raise exception 'Risk creation mismatch';end if;n:=n+1;
 perform public.save_project_risk(r,null,p,d,'QA record risk');if (select count(*) from public.crm_project_risk_history where risk_id=r)<>1 then raise exception 'Retry duplicated history';end if;n:=n+1;
 begin perform public.save_project_risk(r,null,p,d||'{"impact":"Low"}','QA record risk');raise exception 'Changed retry allowed';exception when others then if sqlerrm is distinct from 'Risk ID already used with different data' then raise;end if;end;n:=n+1;
 begin perform public.save_project_risk(r,1,p,d||'{"status":"Closed"}','QA close without evidence');raise exception 'Missing closure allowed';exception when others then if sqlerrm is distinct from 'Closure resolution required' then raise;end if;end;n:=n+1;
 perform public.save_project_risk(r,1,p,d||'{"status":"Mitigating","mitigation":"QA confirm access"}','QA mitigation');if not exists(select 1 from public.crm_project_risk_history where risk_id=r and revision=2 and before_risk->'details'->>'status'='Open' and after_risk->'details'->>'status'='Mitigating' and actor_id=a) then raise exception 'History mismatch';end if;n:=n+1;
 begin perform public.save_project_risk(r,1,p,d,'QA stale update');raise exception 'Stale update allowed';exception when others then if sqlerrm is distinct from 'Current risk version and fixed project required' then raise;end if;end;n:=n+1;
 perform public.save_project_risk(r,2,p,d||'{"status":"Closed","resolution":"QA access confirmed"}','QA close resolved risk');if not exists(select 1 from public.crm_project_risks where id=r and version=3 and details->>'status'='Closed') then raise exception 'Closure mismatch';end if;n:=n+1;
 begin update public.crm_project_risks set version=99 where id=r;raise exception 'Direct write allowed';exception when insufficient_privilege then null;end;n:=n+1;
 begin delete from public.crm_project_risk_history where risk_id=r;raise exception 'History delete allowed';exception when insufficient_privilege then null;end;n:=n+1;
 perform set_config('request.jwt.claim.sub',m::text,true);if not exists(select 1 from public.crm_project_risks where id=r) then raise exception 'Assigned manager cannot read';end if;n:=n+1;
 perform public.save_project_risk(r,3,p,d,'QA manager reopens risk');if not exists(select 1 from public.crm_project_risk_history where risk_id=r and revision=4 and actor_id=m) then raise exception 'Manager revision missing';end if;n:=n+1;
 execute 'reset role';delete from public.project_assignments where project_id=p and technician_id=m;execute 'set local role authenticated';if exists(select 1 from public.crm_project_risks where id=r) then raise exception 'Revoked manager can read';end if;n:=n+1;
 begin perform public.save_project_risk(r,4,p,d,'QA revoked manager edit');raise exception 'Revoked manager edit allowed';exception when others then if sqlerrm is distinct from 'Assigned project manager access required' then raise;end if;end;n:=n+1;
 perform set_config('request.jwt.claim.sub',u::text,true);if exists(select 1 from public.crm_project_risks where id=r) or exists(select 1 from public.crm_project_risk_history where risk_id=r) then raise exception 'Client read allowed';end if;n:=n+1;
 begin perform public.save_project_risk(r,3,p,d,'QA forbidden client edit');raise exception 'Client edit allowed';exception when others then if sqlerrm is distinct from 'Assigned project manager access required' then raise;end if;end;n:=n+1;
 execute 'reset role';if has_function_privilege('anon','public.save_project_risk(uuid,integer,uuid,jsonb,text)','EXECUTE') then raise exception 'Anonymous RPC allowed';end if;n:=n+1;
 perform set_config('qa.risk_result',jsonb_build_object('passed',true,'assertions',n,'fixtures_rollback',true)::text,true);
end$$;
select current_setting('qa.risk_result')::jsonb as qa_result;
rollback;
